<?php
 namespace Pterodactyl\Http\Controllers\Admin\Dezerx; use Illuminate\Http\Request; use Illuminate\Http\RedirectResponse; use Prologue\Alerts\AlertsMessageBag; use Pterodactyl\Services\Dezerx\Addons; use Pterodactyl\Services\Dezerx\EggRules; use Pterodactyl\Http\Controllers\Controller; class EggRulesController extends Controller { public function __construct(private readonly AlertsMessageBag $alert) { } public function store(Request $request): RedirectResponse { $data = $this->data($request); if (EggRules::store($data['eggs'], $data['allowed'])) { $this->alert->success('That egg rule has been added.')->flash(); } else { $this->alert->danger('That egg rule was not added: the panel holds ' . EggRules::MAX . ' of them, which is as many as it keeps.')->flash(); } return $this->back(); } public function update(Request $request, string $rule): RedirectResponse { $data = $this->data($request); if (EggRules::update($rule, $data['eggs'], $data['allowed'])) { $this->alert->success('That egg rule has been saved.')->flash(); } else { $this->alert->danger('That egg rule no longer exists. It may have been removed in another tab.')->flash(); } return $this->back(); } public function destroy(string $rule): RedirectResponse { EggRules::delete($rule); $this->alert->success('That egg rule has been removed.')->flash(); return $this->back(); } private function data(Request $request): array { return $request->validate([ 'eggs' => ['required', 'array', 'min:1'], 'eggs.*' => ['string', 'max:64'], 'allowed' => ['required', 'array', 'min:1'], 'allowed.*' => ['string', 'max:64'], ], [ 'eggs.required' => 'Pick at least one egg the rule applies to.', 'allowed.required' => 'Pick at least one egg those servers may switch to.', ]); } private function back(): RedirectResponse { return redirect()->to(route('admin.dezerx.addons.show', Addons::EGG_SWITCHER) . '#egg-rules'); } } 